import 'dart:io';
import 'package:path/path.dart' as p;
import '../domain/entities/managed_environment.dart';

/// Health assessment and violation report generated by the resource governor.
class ResourceHealthReport {
  final double cpuPercent;
  final double memoryMb;
  final double diskMb;

  final bool isCpuWarning;
  final bool isCpuCritical;
  final bool isMemoryWarning;
  final bool isMemoryCritical;
  final bool isDiskWarning;
  final bool isDiskCritical;

  final List<String> warnings;
  final List<String> recommendedMitigations;

  const ResourceHealthReport({
    required this.cpuPercent,
    required this.memoryMb,
    required this.diskMb,
    required this.isCpuWarning,
    required this.isCpuCritical,
    required this.isMemoryWarning,
    required this.isMemoryCritical,
    required this.isDiskWarning,
    required this.isDiskCritical,
    required this.warnings,
    required this.recommendedMitigations,
  });

  bool get isSafe => !isCpuCritical && !isMemoryCritical && !isDiskCritical;
  bool get hasWarnings => warnings.isNotEmpty;
}

/// Governor that guards against gVisor micro-VM container crashes by enforcing strict
/// ceilings on processor (< 80%), memory (< 12GB), and disk (< 6GB).
/// Configures resource flags and automatic cache purges across the Top 20 popular programming languages.
class EnvironmentResourceGovernor {
  static const double cpuCeilingPercent = 80.0;
  static const double cpuWarningPercent = 70.0;

  static const double memoryCeilingMb = 12288.0; // 12GB
  static const double memoryWarningMb = 9830.4; // 80% of 12GB

  static const double diskCeilingMb = 6144.0; // 6GB
  static const double diskWarningMb = 4915.2; // 80% of 6GB

  /// The Top 20 popular programming languages and runtimes supported by the resource governor.
  static const List<String> supportedLanguages = [
    'JavaScript / TypeScript (Node.js)',
    'Bun',
    'Deno',
    'Python',
    'Rust',
    'Go',
    'Java / Kotlin (JVM)',
    'Gradle / Android',
    'C# / .NET',
    'Dart / Flutter',
    'Elixir / Erlang',
    'Ruby',
    'PHP',
    'C / C++',
    'Swift',
    'Scala',
    'Haskell',
    'OCaml',
    'Zig',
    'Julia',
  ];

  /// Evaluates current environment resource metrics and produces a health report.
  ResourceHealthReport assessEnvironment(ManagedEnvironment env) {
    final cpu = env.cpuUsagePercent;
    final mem = env.memoryUsageMb;
    final disk = env.diskUsageMb;

    final isCpuCrit = cpu >= cpuCeilingPercent;
    final isCpuWarn = cpu >= cpuWarningPercent;

    final isMemCrit = mem >= memoryCeilingMb;
    final isMemWarn = mem >= memoryWarningMb;

    final isDiskCrit = disk >= diskCeilingMb;
    final isDiskWarn = disk >= diskWarningMb;

    final List<String> warnings = [];
    final List<String> mitigations = [];

    if (isCpuCrit) {
      warnings.add('CRITICAL: CPU usage at ${cpu.toStringAsFixed(1)}% exceeds 80% limit.');
      mitigations.add('Throttle parallel build workers to 1 and pause non-essential background tasks.');
    } else if (isCpuWarn) {
      warnings.add('WARNING: CPU usage at ${cpu.toStringAsFixed(1)}% approaches 80% limit.');
      mitigations.add('Reduce compile concurrency.');
    }

    if (isMemCrit) {
      warnings.add('CRITICAL: RAM usage (${mem.toStringAsFixed(0)}MB) exceeds 12GB limit.');
      mitigations.add('Trigger garbage collection and inject heap limits (--max-old-space-size=4096).');
    } else if (isMemWarn) {
      warnings.add('WARNING: RAM usage (${mem.toStringAsFixed(0)}MB) is above 80% of 12GB limit.');
      mitigations.add('Avoid loading large trace files into unbounded memory.');
    }

    if (isDiskCrit) {
      warnings.add('CRITICAL: Disk consumption (${disk.toStringAsFixed(0)}MB) exceeds 6GB limit.');
      mitigations.add('Execute emergency cache cleanup on compiler output directories.');
    } else if (isDiskWarn) {
      warnings.add('WARNING: Disk consumption (${disk.toStringAsFixed(0)}MB) is approaching 6GB.');
      mitigations.add('Prune transient build outputs.');
    }

    return ResourceHealthReport(
      cpuPercent: cpu,
      memoryMb: mem,
      diskMb: disk,
      isCpuWarning: isCpuWarn,
      isCpuCritical: isCpuCrit,
      isMemoryWarning: isMemWarn,
      isMemoryCritical: isMemCrit,
      isDiskWarning: isDiskWarn,
      isDiskCritical: isDiskCrit,
      warnings: warnings,
      recommendedMitigations: mitigations,
    );
  }

  /// Injects memory-safe runtime and compiler flags across the Top 20 popular programming
  /// languages and runtimes to guarantee container stability within 12GB RAM and 80% CPU.
  Map<String, String> getSafeEnvironmentVariables() {
    return {
      // 1. JavaScript / TypeScript (Node.js) - Caps V8 heap to 4GB
      'NODE_OPTIONS': '--max-old-space-size=4096',
      // 2. Bun - Enables aggressive GC and caps memory to 4GB
      'BUN_GARBAGE_COLLECTOR_LEVEL': '1',
      'BUN_MAX_MEMORY': '4096MB',
      // 3. Deno - Caps V8 heap
      'DENO_V8_FLAGS': '--max-old-space-size=4096',
      // 4. Python - Prevents bytecode caching and bounds memory allocation
      'PYTHONDONTWRITEBYTECODE': '1',
      'PYTHONMALLOC': 'malloc',
      'PYTHONHASHSEED': '0',
      // 5. Rust / Cargo - Limits parallel build jobs and codegen units to prevent RAM spikes
      'CARGO_BUILD_JOBS': '2',
      'RUSTFLAGS': '-C codegen-units=1',
      // 6. Go - Caps thread count, directs cache, and limits total memory
      'GOMAXPROCS': '2',
      'GOMEMLIMIT': '4GiB',
      'GOCACHE': '/tmp/go-cache',
      // 7. Java / Kotlin / JVM - Limits max heap to 4GB with G1GC
      'JAVA_TOOL_OPTIONS': '-Xmx4g -XX:+UseG1GC',
      // 8. Gradle / Android - Limits Gradle daemon memory footprint
      'GRADLE_OPTS': '-Xmx4g -XX:+UseG1GC -Dorg.gradle.daemon=false',
      // 9. C# / .NET - Enforces 4GB GC hard limit and workstation GC
      'DOTNET_GCHeapHardLimit': '0x100000000',
      'DOTNET_GCServer': '0',
      'DOTNET_CLI_TELEMETRY_OPTOUT': '1',
      // 10. Dart / Flutter - Caps old gen heap size to 4GB
      'DART_VM_OPTIONS': '--old_gen_heap_size=4096',
      // 11. Elixir / Erlang (BEAM) - Caps ports and limits scheduler threads
      'ERL_MAX_PORTS': '1024',
      'ERL_FLAGS': '+MBas aobf +MBlmbcs 512 +S 2:2',
      // 12. Ruby - Regulates garbage collection heap growth
      'RUBY_GC_HEAP_GROWTH_FACTOR': '1.2',
      'RUBY_GC_MALLOC_LIMIT': '67108864',
      // 13. PHP - Constrains memory limit
      'PHP_INI_SCAN_DIR': '/tmp',
      // 14. C / C++ (Make / CMake) - Restricts parallel build concurrency
      'MAKEFLAGS': '-j2',
      'CMAKE_BUILD_PARALLEL_LEVEL': '2',
      // 15. Swift - Restricts parallel build workers
      'SWIFT_BUILD_JOBS': '2',
      // 16. Scala / sbt - Sets heap ceiling
      'SBT_OPTS': '-Xmx4g -XX:+UseG1GC',
      // 17. Haskell (GHC) - Limits runtime system memory to 4GB
      'GHCRTS': '-M4G -c',
      // 18. OCaml / Opam - Configures minor heap and compaction overhead
      'OCAMLRUNPARAM': 's=4M,i=32M,o=150',
      // 19. Zig - Directs global cache to managed path
      'ZIG_GLOBAL_CACHE_DIR': '/tmp/zig-cache',
      // 20. Julia - Limits worker threads
      'JULIA_NUM_THREADS': '2',
      // Shared / Temp
      'TMPDIR': '/tmp',
    };
  }

  /// Calculates safe task concurrency based on current processor load.
  int suggestConcurrency(double cpuPercent) {
    if (cpuPercent >= 75.0) return 1;
    if (cpuPercent >= 50.0) return 2;
    return 4;
  }

  /// Automatically prunes transient build artifacts, temporary compiler caches,
  /// and dangling test snapshots across Top 20 languages to stay strictly under the 6GB disk limit.
  Future<int> performAutoPrune(String targetDirectoryPath) async {
    int bytesFreed = 0;
    final dir = Directory(targetDirectoryPath);
    if (!await dir.exists()) return 0;

    // Prune patterns covering Top 20 popular programming languages
    final prunableFilePatterns = [
      RegExp(r'\.tmp$'),
      RegExp(r'\.trace$'),
      RegExp(r'\.log$'),
      RegExp(r'\.pyc$'),
      RegExp(r'\.pyo$'),
      RegExp(r'ninja_deps$'),
      RegExp(r'ninja_log$'),
    ];

    final prunableDirNames = {
      // Rust
      'incremental',
      // Go
      'go-cache',
      // JavaScript / TypeScript / Bun / Deno
      '.cache',
      'playwright-report',
      'test-results',
      // Python
      '__pycache__',
      '.pytest_cache',
      '.mypy_cache',
      '.ruff_cache',
      // C# / .NET
      'obj',
      // Java / Kotlin / Gradle
      '.gradle',
      // Dart / Flutter
      '.dart_tool',
      // Elixir / Erlang
      '.rebar3',
      // Zig
      '.zig-cache',
      // C / C++
      'CMakeFiles',
    };

    try {
      await for (final entity in dir.list(recursive: true, followLinks: false)) {
        if (entity is File) {
          final filename = p.basename(entity.path);
          final shouldPrune = prunableFilePatterns.any((pat) => pat.hasMatch(filename));
          if (shouldPrune) {
            final size = await entity.length();
            await entity.delete();
            bytesFreed += size;
          }
        } else if (entity is Directory) {
          final dirname = p.basename(entity.path);
          if (prunableDirNames.contains(dirname)) {
            // Delete transient cache directories
            try {
              final stat = await entity.stat();
              bytesFreed += stat.size;
              await entity.delete(recursive: true);
            } catch (_) {}
          }
        }
      }
    } catch (_) {
      // Best-effort cleanup without throwing
    }

    return bytesFreed;
  }
}
